    const colsXml=`<cols>${cols.map((c,i)=>`<col min="${i+1}" max="${i+1}" width="${c.width||({money:15,date:12,pct:9,num:10,int:9}[c.type]||18)}" customWidth="1"/>`).join('')}</cols>`;
