/* ---------- tính toán chung (có nhớ đệm) ---------- */
const cu=n=>n?(+n.packPrice||0)/(+n.packSize||1):0;
const UNITS=['g','ml','cái','kg','lít','gói','hộp','lon'];
const GCOL={'Cà phê':'#6d4c41','Trà':'#2e7d32','Trà sữa':'#ad5b8e','Đá xay':'#0277bd','Nước ép':'#ef6c00','Bánh':'#c0841a'};
const gcol=g=>GCOL[g]||'#1565C0';
const ini=s=>String(s||'?').split(/\s+/).filter(Boolean).slice(0,2).map(w=>w[0]).join('').toUpperCase();
function fq(q,u){q=+q||0;if(u==='g'&&Math.abs(q)>=1000)return fmtD(q/1000,2)+' kg';if(u==='ml'&&Math.abs(q)>=1000)return fmtD(q/1000,2)+' lít';return fmtD(q,1)+' '+(u||'')}
function useOf(m,s,q,nlm,cb){if(!m)return;let i=m.sizes.findIndex(x=>x.n===s);if(i<0)i=0;m.rec.forEach(r=>{const v=(+r.q[i]||0)*q;if(v&&nlm[r.nl])cb(r.nl,v)})}
let MEMO={};
function C(){const k=S.updated+'|'+S.orders.length+'|'+S.imports.length+'|'+S.counts.length+'|'+S.nl.length+'|'+S.menu.length;
  if(MEMO.S===S&&MEMO.k===k)return MEMO.v;
  const nl={},mm={};S.nl.forEach(n=>nl[n.id]=n);S.menu.forEach(m=>mm[m.id]=m);
  const cost={};S.menu.forEach(m=>{cost[m.id]={};m.sizes.forEach((s,i)=>cost[m.id][s.n]=sum(m.rec,r=>(+r.q[i]||0)*cu(nl[r.nl])))});
  const st={},use7={},d7=addDays(TODAYS,-6);S.nl.forEach(n=>{st[n.id]=+n.open||0;use7[n.id]=0});
  S.imports.forEach(p=>p.lines.forEach(l=>{const n=nl[l.nl];if(n)st[l.nl]+=(+l.q||0)*(+n.packSize||1)}));
  S.counts.forEach(k=>k.lines.forEach(l=>{if(st[l.nl]!=null)st[l.nl]+=(+l.act||0)-(+l.sys||0)}));
  S.orders.forEach(o=>{const rec=o.d>=d7&&o.d<=TODAYS;o.lines.forEach(l=>useOf(mm[l.m],l.s,l.q,nl,(id,q)=>{st[id]-=q;if(rec)use7[id]+=q}))});
  MEMO={S,k,v:{nl,mm,cost,st,use7}};return MEMO.v}
function nlSt(n,c){const s=c.st[n.id]||0;if(s<=0)return 'zero';if(s<=(+n.min||0))return 'low';return 'ok'}
const STT={ok:['ok','Đủ dùng'],low:['low','Sắp hết'],zero:['zero','Hết']};
const daysLeft=(n,c)=>{const a=(c.use7[n.id]||0)/7;return a>0?Math.max(0,(c.st[n.id]||0)/a):Infinity};
const mCost=(m,s,c)=>((c||C()).cost[m.id]||{})[s]||0;
function oSum(o,c){let g=0,cg=0,items=0;o.lines.forEach(l=>{g+=l.q*l.p;cg+=l.q*(((c.cost[l.m]||{})[l.s])||0);items+=l.q});const disc=Math.min(g,+o.disc||0);return {g,disc,net:g-disc,cogs:cg,gp:g-disc-cg,items}}
function agg(f,t){const c=C(),o={rev:0,gross:0,disc:0,cogs:0,n:0,items:0,byM:{},hour:Array(24).fill(0),hourN:Array(24).fill(0),pay:{},ch:{},day:{},days:new Set()};
  S.orders.forEach(x=>{if(x.d<f||x.d>t)return;const s=oSum(x,c);o.rev+=s.net;o.gross+=s.g;o.disc+=s.disc;o.cogs+=s.cogs;o.n++;o.items+=s.items;o.days.add(x.d);
    const h=Math.min(23,+String(x.t||'0').slice(0,2)||0);o.hour[h]+=s.net;o.hourN[h]++;o.pay[x.pay||'Khác']=(o.pay[x.pay||'Khác']||0)+s.net;o.ch[x.ch||'Khác']=(o.ch[x.ch||'Khác']||0)+s.net;
    const dd=o.day[x.d]=o.day[x.d]||{rev:0,cogs:0,n:0,items:0,disc:0};dd.rev+=s.net;dd.cogs+=s.cogs;dd.n++;dd.items+=s.items;dd.disc+=s.disc;
    const k=s.g?s.net/s.g:0;x.lines.forEach(l=>{const b=o.byM[l.m]=o.byM[l.m]||{q:0,rev:0,cogs:0,sz:{}};b.q+=l.q;b.rev+=l.q*l.p*k;b.cogs+=l.q*(((c.cost[l.m]||{})[l.s])||0);b.sz[l.s]=(b.sz[l.s]||0)+l.q})});
  o.gp=o.rev-o.cogs;o.nd=o.days.size;return o}
function daySeries(n){const keys=[];for(let i=n-1;i>=0;i--)keys.push(addDays(TODAYS,-i));const a=agg(keys[0],TODAYS);return {keys,labels:keys.map(k=>k.slice(8)+'/'+k.slice(5,7)),rev:keys.map(k=>(a.day[k]||{}).rev||0),gp:keys.map(k=>{const d=a.day[k];return d?d.rev-d.cogs:0}),n:keys.map(k=>(a.day[k]||{}).n||0),items:keys.map(k=>(a.day[k]||{}).items||0)}}
const nextNo=(arr,pre,len)=>{let m=0;arr.forEach(x=>{const v=parseInt(String(x.no).replace(/\D/g,''))||0;if(v>m)m=v});return pre+String(m+1).padStart(len,'0')};
const mName2=(id,c)=>{const m=(c||C()).mm[id];return m?m.name:'(món đã xóa)'};

