const MF={q:'',g:'',on:''};
function renderMenu(){const e=$('#page-menu'),c=C();
  if(!e.dataset.built){e.innerHTML=`<div class="toolbar"><div class="search grow">${IC.search}<input class="inp" id="mnQ" placeholder="Tìm món..."></div><select class="inp" id="mnG"></select><select class="inp" id="mnOn"><option value="">Đang bán và ngừng bán</option><option value="1">Đang bán</option><option value="0">Ngừng bán</option></select><button class="btn pri" onclick="menuOpen()">${IC.plus}Thêm món</button></div><div id="mnSum"></div><div class="menu-grid" id="mnL"></div>`;
    $('#mnQ').oninput=ev=>{MF.q=ev.target.value;renderMenu()};$('#mnG').onchange=ev=>{MF.g=ev.target.value;renderMenu()};$('#mnOn').onchange=ev=>{MF.on=ev.target.value;renderMenu()};e.dataset.built=1}
  const grps=[...new Set(S.menu.map(m=>m.grp))];$('#mnG').innerHTML='<option value="">Mọi nhóm món</option>'+grps.map(g=>`<option ${g===MF.g?'selected':''}>${esc(g)}</option>`).join('');
  const list=S.menu.filter(m=>(!MF.q||matchQ(MF.q,m.code+' '+m.name))&&(!MF.g||m.grp===MF.g)&&(MF.on===''||(m.on!==false)===(MF.on==='1'))).sort((a,b)=>a.code.localeCompare(b.code));
  const fcs=[];S.menu.forEach(m=>m.sizes.forEach(s=>{if(s.p)fcs.push(mCost(m,s.n,c)/s.p*100)}));const avgFc=fcs.length?sum(fcs)/fcs.length:0,hi=fcs.filter(x=>x>35).length;
  $('#mnSum').innerHTML=`<div class="card" style="padding:14px 18px;margin-bottom:16px;display:flex;gap:28px;flex-wrap:wrap;align-items:center"><div><small class="muted">Số món</small><b style="display:block;font-size:18px">${S.menu.length} món · ${S.menu.filter(m=>m.on!==false).length} đang bán</b></div><div><small class="muted">% giá vốn trung bình</small><b style="display:block;font-size:18px" class="fc ${avgFc<=30?'g':avgFc<=35?'w':'b'}">${pct(avgFc)}</b></div><div><small class="muted">Size có giá vốn trên 35%</small><b style="display:block;font-size:18px;color:${hi?'var(--danger)':'var(--in)'}">${hi}</b></div><div class="muted" style="font-size:12.5px;max-width:420px">Giá vốn mỗi ly tự tính từ định lượng và giá nhập nguyên liệu. Đổi giá nhập ở mục Nguyên liệu là giá vốn cập nhật ngay.</div></div>`;
  $('#mnL').innerHTML=list.length?list.map(m=>`<div class="card mn" style="${m.on===false?'opacity:.6':''}"><div class="mn-h"><span class="av" style="background:${gcol(m.grp)}">${esc(ini(m.name))}</span><div style="min-width:0"><b>${esc(m.name)}</b><small>${esc(m.code)} · <span class="tag cat">${esc(m.grp)}</span>${m.on===false?' <span class="tag gray">Ngừng bán</span>':''}</small></div></div>
    <table><thead><tr><th>Size</th><th class="n">Giá bán</th><th class="n">Giá vốn</th><th class="n">Lãi gộp</th><th class="n">% vốn</th></tr></thead><tbody>${m.sizes.map(s=>{const cg=mCost(m,s.n,c),f=s.p?cg/s.p*100:0;return `<tr><td><b>${esc(s.n)}</b></td><td class="n">${fmt(s.p)}</td><td class="n">${fmt(cg)}</td><td class="n">${fmt(s.p-cg)}</td><td class="n"><span class="fc ${f<=30?'g':f<=35?'w':'b'}">${pct(f,0)}</span></td></tr>`}).join('')}</tbody></table>
    <div class="rc">${m.rec.map(r=>{const n=c.nl[r.nl];return n?`${esc(n.name)} <b>${r.q.map(q=>fmtD(q,1)).join('/')}</b> ${esc(n.unit)}`:''}).filter(Boolean).join(' · ')||'<i>Chưa có định lượng</i>'}</div>
    <div class="act"><button class="btn sm" onclick="menuOpen('${m.id}')">${IC.edit}Sửa định lượng</button><button class="btn sm" onclick="menuToggle('${m.id}')">${m.on===false?'Bán lại':'Ngừng bán'}</button><button class="btn sm ico danger" style="margin-left:auto" title="Xóa món" onclick="menuDel('${m.id}')">${IC.trash}</button></div></div>`).join(''):'<div class="card empty" style="grid-column:1/-1">Chưa có món nào. <button class="btn pri" onclick="menuOpen()">Thêm món</button></div>'}
let MEDT=null;
function menuOpen(id){const m=id?S.menu.find(x=>x.id===id):null;
  MEDT=m?JSON.parse(JSON.stringify(m)):{id:'',code:nextNo(S.menu.map(x=>({no:x.code})),'M',2),name:'',grp:'Cà phê',on:true,sizes:[{n:'M',p:0},{n:'L',p:0}],rec:[]};
  openModal(`<div class="modal-h"><h3>${m?'Sửa món & định lượng':'Thêm món mới'}</h3><button class="x" onclick="closeModal()">×</button></div>
  <div class="modal-b"><div class="row3"><div class="fg"><label class="f">Mã món *</label><input class="inp" id="meCode" value="${esc(MEDT.code)}"></div><div class="fg"><label class="f">Tên món *</label><input class="inp" id="meName" value="${esc(MEDT.name)}" placeholder="VD: Cà phê sữa đá"></div><div class="fg"><label class="f">Nhóm món</label><input class="inp" id="meGrp" list="meGl" value="${esc(MEDT.grp)}"><datalist id="meGl">${[...new Set(['Cà phê','Trà','Trà sữa','Đá xay','Nước ép','Bánh',...S.menu.map(x=>x.grp)])].map(g=>`<option>${esc(g)}</option>`).join('')}</datalist></div></div>
  <label class="f">Size và giá bán</label><div class="szc" id="meSz"></div>
  <div class="sec-t" style="margin-top:18px">Định lượng cho 1 ly / 1 phần theo từng size</div>
  <div class="tbl-wrap"><table class="lines rmx" id="meT"></table></div>
  <input class="inp" id="meAdd" placeholder="+ Thêm nguyên liệu vào công thức: gõ tên rồi chọn" style="margin-top:10px;border-style:dashed">
  <p class="fhint" style="margin-top:8px">Ghi theo đơn vị tính của nguyên liệu (g, ml, cái). Size nào không dùng nguyên liệu đó thì để 0.</p></div>
  <div class="modal-f"><button class="btn" onclick="closeModal()">Hủy</button><button class="btn pri" onclick="menuSave()">${IC.save}Lưu món</button></div>`,'wide');
  acBind($('#meAdd'),q=>S.nl.filter(n=>!MEDT.rec.some(r=>r.nl===n.id)&&(!q||matchQ(q,n.code+' '+n.name))).map(n=>({id:n.id,title:n.name,sub:`${esc(n.code)} · ${esc(n.unit)} · ${fmtD(cu(n),2)} ₫/${esc(n.unit)}`})),it=>{MEDT.rec.push({nl:it.id,q:MEDT.sizes.map(()=>0)});$('#meAdd').value='';meDraw();const i=$$('#meT .cin');if(i.length)i[i.length-MEDT.sizes.length].focus()});
  meDraw()}
function meSync(){MEDT.code=$('#meCode').value.trim();MEDT.name=$('#meName').value.trim();MEDT.grp=$('#meGrp').value.trim()}
function meDraw(){const c=C();
  $('#meSz').innerHTML=MEDT.sizes.map((s,i)=>`<div class="sz-i"><input class="cin l" value="${esc(s.n)}" placeholder="Size" onchange="MEDT.sizes[${i}].n=this.value.trim();meDraw()" style="width:64px"><input class="cin" value="${s.p?fmt(s.p):''}" placeholder="Giá bán" oninput="MEDT.sizes[${i}].p=parseNum(this.value);meFoot()" onblur="this.value=MEDT.sizes[${i}].p?fmt(MEDT.sizes[${i}].p):''">${MEDT.sizes.length>1?`<button class="xbtn" title="Bỏ size" onclick="MEDT.sizes.splice(${i},1);MEDT.rec.forEach(r=>r.q.splice(${i},1));meDraw()">✕</button>`:''}</div>`).join('')+`<button class="btn sm" onclick="MEDT.sizes.push({n:'',p:0});MEDT.rec.forEach(r=>r.q.push(0));meDraw()">${IC.plus}Thêm size</button>`;
  $('#meT').innerHTML=`<thead><tr><th>Nguyên liệu</th><th class="n">Giá vốn/đv</th>${MEDT.sizes.map(s=>`<th class="n" style="width:100px">Size ${esc(s.n||'?')}</th>`).join('')}<th style="width:36px"></th></tr></thead>
    <tbody>${MEDT.rec.map((r,i)=>{const n=c.nl[r.nl];return `<tr><td><b>${esc(n?n.name:'(đã xóa)')}</b><br><small class="muted">${esc(n?n.unit:'')}</small></td><td class="n muted">${n?fmtD(cu(n),2):''}</td>${MEDT.sizes.map((s,j)=>`<td><input class="cin" type="number" step="any" min="0" value="${r.q[j]||''}" placeholder="0" oninput="MEDT.rec[${i}].q[${j}]=parseNum(this.value);meFoot()"></td>`).join('')}<td><button class="xbtn" onclick="MEDT.rec.splice(${i},1);meDraw()">✕</button></td></tr>`}).join('')||`<tr><td colspan="${MEDT.sizes.length+3}" class="empty" style="padding:18px">Chưa có nguyên liệu nào trong công thức</td></tr>`}</tbody>
    <tfoot id="meF"></tfoot>`;meFoot()}
function meFoot(){const c=C(),cost=MEDT.sizes.map((s,j)=>sum(MEDT.rec,r=>(+r.q[j]||0)*cu(c.nl[r.nl])));
  $('#meF').innerHTML=`<tr><td colspan="2">Giá vốn 1 ly</td>${cost.map(v=>`<td class="n">${fmt(v)}</td>`).join('')}<td></td></tr><tr><td colspan="2">Lãi gộp 1 ly</td>${MEDT.sizes.map((s,j)=>`<td class="n" style="color:var(--in)">${fmt((+s.p||0)-cost[j])}</td>`).join('')}<td></td></tr><tr><td colspan="2">% giá vốn / giá bán</td>${MEDT.sizes.map((s,j)=>{const f=s.p?cost[j]/s.p*100:0;return `<td class="n"><span class="fc ${f<=30?'g':f<=35?'w':'b'}">${s.p?pct(f):'-'}</span></td>`}).join('')}<td></td></tr>`}
function menuSave(){meSync();if(!MEDT.code||!MEDT.name)return toast('Chưa điền mã hoặc tên món','err');
  if(S.menu.some(x=>x.code.toLowerCase()===MEDT.code.toLowerCase()&&x.id!==MEDT.id))return toast('Mã món '+MEDT.code+' đã có','err');
  const names=MEDT.sizes.map(s=>s.n);if(names.some(n=>!n))return toast('Có size chưa đặt tên','err');if(new Set(names).size!==names.length)return toast('Tên size bị trùng','err');
  if(MEDT.sizes.some(s=>!(s.p>0)))return toast('Chưa điền giá bán cho đủ các size','err');
  MEDT.rec=MEDT.rec.filter(r=>r.q.some(q=>q>0));
  if(MEDT.id){const i=S.menu.findIndex(x=>x.id===MEDT.id);S.menu[i]=MEDT}else{MEDT.id='m'+uid();S.menu.push(MEDT)}
  save();closeModal();toast('Đã lưu món '+MEDT.name);rerender()}
function menuToggle(id){const m=S.menu.find(x=>x.id===id);m.on=m.on===false;save();toast(m.on?'Đã mở bán lại '+m.name:'Đã ngừng bán '+m.name);rerender()}
async function menuDel(id){const m=S.menu.find(x=>x.id===id);const n=S.orders.filter(o=>o.lines.some(l=>l.m===id)).length;
  if(n)return toast(`Món ${m.name} đã có trong ${fmt(n)} order, không xóa được. Bấm "Ngừng bán" để ẩn khỏi màn hình bán hàng.`,'err');
  if(!await ask(`Xóa món <b>${esc(m.name)}</b> và định lượng của món?`))return;S.menu=S.menu.filter(x=>x.id!==id);save();toast('Đã xóa món');rerender()}

/* =========================================================
   NGUYÊN LIỆU (danh mục dùng chung)
   ========================================================= */
const NLC=crud({id:'nl',el:'#page-nl',name:'nguyên liệu',title:'Nguyên liệu',arr:()=>S.nl,set:a=>S.nl=a,code:{k:'code',pre:'NL',len:3,l:'Mã nguyên liệu'},ph:'Tìm mã, tên nguyên liệu...',
  label:r=>r.name,search:r=>r.code+' '+r.name+' '+r.grp,sort:(a,b)=>a.code.localeCompare(b.code),
  fields:[{k:'code',l:'Mã nguyên liệu',req:1},{k:'name',l:'Tên nguyên liệu',req:1,alias:['ten','tennguyenlieu','nguyenlieu']},{k:'grp',l:'Nhóm',t:'combo',opts:()=>[...new Set(['Cà phê','Sữa & kem','Trà','Bột & siro','Trái cây','Topping','Bao bì','Bánh','Khác',...S.nl.map(n=>n.grp)])],def:'Khác'},
    {k:'unit',l:'Đơn vị tính khi pha chế',t:'select',opts:UNITS,def:'g',hint:'Đơn vị dùng trong định lượng: g, ml, cái...'},{k:'pack',l:'Quy cách nhập',ph:'VD: Gói 1kg, Hộp 1 lít, Cây 50 cái',def:''},
    {k:'packSize',l:'Quy đổi: 1 quy cách = bao nhiêu đơn vị',t:'num',req:1,def:1000,hint:'VD gói 1kg, đơn vị g thì ghi 1000'},{k:'packPrice',l:'Giá nhập 1 quy cách (₫)',t:'money',def:0},
    {k:'min',l:'Tồn tối thiểu (theo đơn vị tính)',t:'num',def:0,hint:'Tồn xuống dưới mức này thì cảnh báo sắp hết'},{k:'open',l:'Tồn đầu (theo đơn vị tính)',t:'num',def:0,hint:'Số có sẵn khi bắt đầu dùng file'},{k:'note',l:'Ghi chú',w2:1}],
  filters:[{all:'Mọi nhóm',opts:()=>[...new Set(S.nl.map(n=>n.grp))],test:(r,v)=>r.grp===v},{all:'Mọi trạng thái',opts:[['ok','Đủ dùng'],['low','Sắp hết'],['zero','Hết']],test:(r,v)=>nlSt(r,C())===v}],
  top:()=>{const c=C(),v=sum(S.nl,n=>Math.max(0,c.st[n.id]||0)*cu(n)),lo=S.nl.filter(n=>nlSt(n,c)==='low').length,z=S.nl.filter(n=>nlSt(n,c)==='zero').length;
    return `<div class="kc-grid">${kc({c:CSSV('--chu-dao'),cb:'var(--cd-nhat)',icon:IC.box,label:'Nguyên liệu',text:S.nl.length,unit:'loại',sub:[...new Set(S.nl.map(n=>n.grp))].length+' nhóm'})}${kc({c:'#0ea5b7',cb:'#e0f7fa',icon:IC.money,label:'Giá trị tồn kho',text:short(v),unit:'₫',sub:'Tính theo giá nhập hiện tại'})}${kc({c:'#e6a100',cb:'var(--warnbg)',icon:IC.warn,label:'Sắp hết',text:lo,unit:'loại',sub:'Dưới mức tồn tối thiểu'})}${kc({c:'#e0384a',cb:'var(--dangerbg)',icon:IC.warn,label:'Đã hết',text:z,unit:'loại',sub:z?'Cần nhập ngay':'Không có'})}</div>`},
  cols:[{l:'Mã',h:r=>`<b>${esc(r.code)}</b>`},{l:'Nguyên liệu',h:r=>`<div class="pcell"><b>${esc(r.name)}</b><small>${esc(r.grp)}</small></div>`},{l:'Quy cách nhập',h:r=>`${esc(r.pack||'')}<br><small class="muted">= ${fmtD(r.packSize)} ${esc(r.unit)}</small>`},
    {l:'Giá nhập',cls:'n',h:r=>fmt(r.packPrice)},{l:'Giá vốn / đv',cls:'n',h:r=>fmtD(cu(r),2)+' <small class="muted">₫/'+esc(r.unit)+'</small>'},
    {l:'Tồn hiện tại',cls:'n',h:r=>{const c=C(),s=c.st[r.id]||0;return `<b style="color:${s<=0?'var(--danger)':s<=r.min?'#b07a00':'inherit'}">${fq(s,r.unit)}</b>${r.packSize>1?`<br><small class="muted">~ ${fmtD(s/r.packSize,1)} ${esc((r.pack||'quy cách').split(' ')[0].toLowerCase())}</small>`:''}`}},
    {l:'Tối thiểu',cls:'n',h:r=>fq(r.min,r.unit)},{l:'Đủ dùng',cls:'n',h:r=>{const d=daysLeft(r,C());return d===Infinity?'<span class="muted">-</span>':fmtD(d,1)+' ngày'}},
    {l:'Giá trị tồn',cls:'n',h:r=>fmt(Math.max(0,C().st[r.id]||0)*cu(r))},{l:'Trạng thái',h:r=>{const k=nlSt(r,C());return `<span class="tag ${STT[k][0]}">${STT[k][1]}</span>`}}],
  rowAct:r=>`<button class="btn sm in" onclick="impAddNl('${r.id}')" title="Lập phiếu nhập">Nhập</button> `,
  foot:rows=>{const c=C();return `<tr><td colspan="9">Tổng ${rows.length} nguyên liệu</td><td class="n">${fmt(sum(rows,n=>Math.max(0,c.st[n.id]||0)*cu(n)))}</td><td colspan="2"></td></tr>`},
  canDel:r=>{const u=S.menu.filter(m=>m.rec.some(x=>x.nl===r.id));if(u.length)return `${r.name} đang có trong định lượng của ${u.map(m=>m.name).slice(0,3).join(', ')}${u.length>3?'...':''}. Bỏ khỏi công thức trước khi xóa.`;if(S.imports.some(p=>p.lines.some(l=>l.nl===r.id)))return r.name+' đã có phiếu nhập, không xóa được.';return null},
  xcols:[]});

/* =========================================================
   PHIẾU NHẬP NGUYÊN LIỆU
   ========================================================= */
let IMD=null;const imdNew=()=>({d:TODAYS,sup:'',note:'',upd:true,lines:[]});
function impAddNl(id){go('imp');impLine(id)}
function impAddLow(){go('imp');const c=C();let n=0;S.nl.filter(x=>nlSt(x,c)!=='ok').forEach(x=>{if(!IMD.lines.some(l=>l.nl===x.id)){IMD.lines.push({k:uid(),nl:x.id,q:Math.max(1,Math.ceil((x.min*3-Math.max(0,c.st[x.id]||0))/x.packSize)),p:x.packPrice});n++}});impLines();toast(n?`Đã thêm ${n} nguyên liệu sắp hết, số lượng là gợi ý, sửa lại nếu cần`:'Không còn nguyên liệu sắp hết nào chưa có trong phiếu')}
function impLine(id){const n=S.nl.find(x=>x.id===id);if(!n)return;const ex=IMD.lines.find(l=>l.nl===id);if(ex){toast(n.name+' đã có trong phiếu');return}IMD.lines.push({k:uid(),nl:id,q:1,p:n.packPrice});impLines();const i=$$('#imL [data-f=q]');if(i.length){i[i.length-1].focus();i[i.length-1].select()}}
function renderImp(){IMD=IMD||imdNew();const e=$('#page-imp'),sups=[...new Set(S.imports.map(p=>p.sup).filter(Boolean))];
  e.innerHTML=`<div class="txl"><div class="card" style="border-top:4px solid var(--in)"><div class="card-h"><h3>PHIẾU NHẬP NGUYÊN LIỆU</h3><span class="tag in">Số ${nextNo(S.imports,'PN',4)}</span><div class="r"><button class="btn sm" onclick="impAddLow()">${IC.warn}Thêm NL sắp hết</button></div></div>
    <div class="card-b"><div class="row3"><div class="fg"><label class="f">Ngày nhập *</label><input class="inp" type="date" id="imD" value="${IMD.d}"></div><div class="fg"><label class="f">Nhà cung cấp</label><input class="inp" id="imS" list="imSl" value="${esc(IMD.sup)}" placeholder="Gõ hoặc chọn"><datalist id="imSl">${sups.map(s=>`<option>${esc(s)}</option>`).join('')}</datalist></div><div class="fg"><label class="f">Ghi chú</label><input class="inp" id="imN" value="${esc(IMD.note)}"></div></div>
    <label style="display:flex;gap:8px;align-items:center;font-size:13px"><input type="checkbox" id="imU" ${IMD.upd?'checked':''}> Cập nhật giá nhập mới vào danh mục nguyên liệu (giá vốn các món tự tính lại)</label></div>
    <div class="sec"><div class="sec-t">Nguyên liệu trong phiếu <span class="cnt" id="imC">0</span></div>
    <div class="tbl-wrap"><table class="lines" style="--tone:var(--in)"><thead><tr><th class="c" style="width:36px">#</th><th>Nguyên liệu</th><th>Quy cách</th><th class="n" style="width:100px">SL nhập</th><th class="n">Quy đổi</th><th class="n" style="width:130px">Đơn giá / quy cách</th><th class="n">Thành tiền</th><th style="width:36px"></th></tr></thead><tbody id="imL"></tbody></table></div>
    <input class="inp" id="imAdd" placeholder="+ Thêm nguyên liệu: gõ mã hoặc tên rồi chọn (Enter)" style="margin-top:10px;border-style:dashed"></div></div>
    <div class="side"><div class="card sum" style="border-top:4px solid var(--in)"><small class="lb">Tổng tiền phiếu nhập</small><div class="big" id="imT" style="color:var(--in)">0 ₫</div><div class="kv2"><span>Số nguyên liệu</span><b id="imN2">0</b></div><div class="words" id="imW"></div>
    <div class="acts"><button class="btn in" onclick="impSave()">${IC.save}Lưu phiếu nhập</button><button class="btn" onclick="impSave(true)">${IC.print}Lưu & in phiếu</button><button class="lnk" onclick="IMD=imdNew();renderImp()">Làm lại phiếu</button></div></div></div></div>
    <div class="card"><div class="card-h"><h3>Phiếu nhập đã lập</h3><span class="hint">${S.imports.length} phiếu · ${short(sum(S.imports,p=>sum(p.lines,l=>l.q*l.p)))} ₫</span></div><div id="imH"></div></div>`;
  $('#imD').oninput=ev=>IMD.d=ev.target.value;$('#imS').oninput=ev=>IMD.sup=ev.target.value;$('#imN').oninput=ev=>IMD.note=ev.target.value;$('#imU').onchange=ev=>IMD.upd=ev.target.checked;
  acBind($('#imAdd'),q=>{const c=C();return S.nl.filter(n=>!q||matchQ(q,n.code+' '+n.name)).sort((a,b)=>q?0:(nlSt(a,c)==='ok')-(nlSt(b,c)==='ok')).map(n=>({id:n.id,title:n.name,sub:`${esc(n.code)} · ${esc(n.pack||'')} · tồn <b style="color:${nlSt(n,c)==='ok'?'inherit':'var(--danger)'}">${fq(c.st[n.id]||0,n.unit)}</b>`,right:IMD.lines.some(l=>l.nl===n.id)?'<span class="tag gray">Đã có</span>':''}))},it=>{$('#imAdd').value='';impLine(it.id)});
  impLines();impHist()}
function impLines(){const tb=$('#imL');if(!tb)return;const c=C();
  tb.innerHTML=IMD.lines.length?IMD.lines.map((l,i)=>{const n=c.nl[l.nl];if(!n)return '';return `<tr data-k="${l.k}"><td class="c muted">${i+1}</td><td><b>${esc(n.name)}</b><br><small class="muted">${esc(n.code)} · tồn ${fq(c.st[n.id]||0,n.unit)}</small></td><td>${esc(n.pack||'')}</td><td><input class="cin" data-f="q" type="number" min="0" step="any" value="${l.q}"></td><td class="n muted" data-qd>${fq(l.q*n.packSize,n.unit)}</td><td><input class="cin" data-f="p" inputmode="numeric" value="${fmt(l.p)}"></td><td class="amt" data-a>${fmt(l.q*l.p)}</td><td><button class="xbtn" onclick="IMD.lines=IMD.lines.filter(x=>x.k!=='${l.k}');impLines()">✕</button></td></tr>`}).join(''):`<tr><td colspan="8" class="empty" style="padding:22px">Chưa có nguyên liệu. Gõ tên ở ô dưới để thêm.</td></tr>`;
  tb.querySelectorAll('tr[data-k]').forEach(tr=>{const l=IMD.lines.find(x=>x.k===tr.dataset.k),n=c.nl[l.nl];
    tr.querySelector('[data-f=q]').oninput=ev=>{l.q=parseNum(ev.target.value);tr.querySelector('[data-qd]').textContent=fq(l.q*n.packSize,n.unit);tr.querySelector('[data-a]').textContent=fmt(l.q*l.p);impTot()};
    const pi=tr.querySelector('[data-f=p]');pi.oninput=ev=>{l.p=parseNum(ev.target.value);tr.querySelector('[data-a]').textContent=fmt(l.q*l.p);impTot()};pi.onblur=()=>pi.value=fmt(l.p)});
  impTot()}
function impTot(){const t=sum(IMD.lines,l=>l.q*l.p);$('#imT').textContent=money(t);$('#imC').textContent=IMD.lines.length;$('#imN2').textContent=IMD.lines.length;$('#imW').innerHTML=t?'Bằng chữ: <b>'+docSo(t)+'</b>':''}
function impSave(andPrint){IMD.d=$('#imD').value;IMD.sup=$('#imS').value.trim();IMD.note=$('#imN').value.trim();
  const ls=IMD.lines.filter(l=>l.q>0);if(!ls.length)return toast('Phiếu chưa có nguyên liệu nào có số lượng','err');if(!IMD.d)return toast('Chưa chọn ngày nhập','err');
  const no=nextNo(S.imports,'PN',4),id='p'+uid();S.imports.push({id,no,d:IMD.d,sup:IMD.sup,note:IMD.note,lines:ls.map(l=>({nl:l.nl,q:l.q,p:l.p}))});
  if(IMD.upd)ls.forEach(l=>{const n=S.nl.find(x=>x.id===l.nl);if(n&&l.p>0)n.packPrice=l.p});
  save();toast(`Đã lưu ${no}: ${ls.length} nguyên liệu, ${money(sum(ls,l=>l.q*l.p))}`);IMD=imdNew();renderImp();if(andPrint)setTimeout(()=>printImp(id),200)}
function impHist(){const box=$('#imH'),c=C(),list=S.imports.slice().sort((a,b)=>b.d.localeCompare(a.d)||b.no.localeCompare(a.no));
  box.innerHTML=list.length?`<div class="tbl-wrap"><table><thead><tr><th>Số phiếu</th><th>Ngày</th><th>Nhà cung cấp</th><th>Nguyên liệu</th><th class="n">Số dòng</th><th class="n">Tổng tiền</th><th></th></tr></thead><tbody>${pgSlice('imH',list,10).map(p=>`<tr><td><b>${p.no}</b></td><td>${vnDate(p.d)}</td><td>${esc(p.sup)}</td><td><div class="muted" style="max-width:320px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${esc(p.lines.map(l=>(c.nl[l.nl]||{}).name+' x'+fmtD(l.q)).join(', '))}</div></td><td class="n">${p.lines.length}</td><td class="n"><b>${fmt(sum(p.lines,l=>l.q*l.p))}</b></td><td class="acts-c"><button class="btn sm ico" title="In phiếu" onclick="printImp('${p.id}')">${IC.print}</button> <button class="btn sm ico danger" title="Xóa" onclick="impDel('${p.id}')">${IC.trash}</button></td></tr>`).join('')}</tbody></table></div>${pgBar('imH',list.length,impHist)}`:'<div class="empty">Chưa có phiếu nhập</div>'}
async function impDel(id){const p=S.imports.find(x=>x.id===id);if(!await ask(`Xóa phiếu nhập <b>${esc(p.no)}</b>? Số nguyên liệu của phiếu sẽ bị trừ khỏi kho.`))return;S.imports=S.imports.filter(x=>x.id!==id);save();toast('Đã xóa phiếu '+p.no);rerender()}
function printImp(id){const p=S.imports.find(x=>x.id===id);if(!p)return;const c=C(),k=co(),[y,m,d]=p.d.split('-'),tot=sum(p.lines,l=>l.q*l.p);
  printHtml(`<div class="vt"><div class="hd"><div><b>Đơn vị: ${esc(k.name||DOTS)}</b><br>Địa chỉ: ${esc(k.addr||DOTS)}</div><div class="r"><b>Mẫu số 01 - VT</b></div></div>
  <h2>PHIẾU NHẬP KHO NGUYÊN LIỆU</h2><div class="dt">Ngày ${d} tháng ${m} năm ${y}</div><div class="so">Số: <b>${esc(p.no)}</b></div>
  <div class="ln">Nhà cung cấp: <b>${esc(p.sup||'')}</b></div><div class="ln">Diễn giải: ${esc(p.note||'')}</div>
  <table><thead><tr><th>STT</th><th>Mã</th><th>Tên nguyên liệu</th><th>Quy cách</th><th>Số lượng</th><th>Quy đổi</th><th>Đơn giá</th><th>Thành tiền</th></tr></thead>
  <tbody>${p.lines.map((l,i)=>{const n=c.nl[l.nl]||{};return `<tr><td class="c">${i+1}</td><td class="c">${esc(n.code||'')}</td><td>${esc(n.name||'')}</td><td>${esc(n.pack||'')}</td><td class="n">${fmtD(l.q)}</td><td class="n">${fq(l.q*(n.packSize||1),n.unit)}</td><td class="n">${fmt(l.p)}</td><td class="n">${fmt(l.q*l.p)}</td></tr>`}).join('')}</tbody>
  <tfoot><tr><td colspan="7" class="c">Cộng</td><td class="n">${fmt(tot)}</td></tr></tfoot></table>
  <div class="ln">Tổng số tiền (viết bằng chữ): <b><i>${docSo(tot)}</i></b></div><div class="sdate">Ngày ${d} tháng ${m} năm ${y}</div>
  <div class="sign" style="--n:3"><div><b>Người lập phiếu</b><i>(Ký, họ tên)</i></div><div><b>Người giao hàng</b><i>(Ký, họ tên)</i></div><div><b>Quản lý quán</b><i>(Ký, họ tên)</i></div></div></div>`)}

/* =========================================================
   KIỂM KÊ KHO
   ========================================================= */
let KK={d:TODAYS,note:'',act:{},q:''};
function renderCount(){const e=$('#page-count');
  e.innerHTML=`<div class="card" style="margin-bottom:18px"><div class="card-h"><h3>Phiếu kiểm kê mới</h3><span class="tag cat">Số ${nextNo(S.counts,'KK',3)}</span><div class="r"><button class="btn" onclick="kkFill()">Điền thực tế = sổ sách</button><button class="btn pri" onclick="kkSave()">${IC.save}Lưu phiếu kiểm kê</button></div></div>
    <div class="card-b"><div class="row3"><div class="fg"><label class="f">Ngày kiểm kê</label><input class="inp" type="date" id="kkD" value="${KK.d}"></div><div class="fg"><label class="f">Ghi chú</label><input class="inp" id="kkN" value="${esc(KK.note)}" placeholder="VD: Kiểm kê cuối tuần"></div><div class="fg"><label class="f">Tìm nguyên liệu</label><input class="inp" id="kkQ" value="${esc(KK.q)}" placeholder="Gõ tên..."></div></div>
    <p class="hint2">Đếm thực tế trong kho rồi ghi vào cột <b>Thực tế</b>. Dòng để trống là không kiểm. Lưu phiếu thì tồn kho được chốt bằng số thực tế, phần chênh lệch là hao hụt (hoặc dư).</p></div>
    <div class="tbl-wrap" id="kkT"></div></div>
    <div class="card"><div class="card-h"><h3>Lịch sử kiểm kê</h3></div><div id="kkH"></div></div>`;
  $('#kkD').oninput=ev=>{KK.d=ev.target.value;kkTable()};$('#kkN').oninput=ev=>KK.note=ev.target.value;$('#kkQ').oninput=ev=>{KK.q=ev.target.value;kkTable()};
  kkTable();kkHist()}
function kkSys(){const R={};xnt('0000-01-01',KK.d||TODAYS).forEach(r=>R[r.n.id]=r.close);return R}
function kkTable(){const sys=kkSys(),list=S.nl.filter(n=>!KK.q||matchQ(KK.q,n.code+' '+n.name)).sort((a,b)=>a.code.localeCompare(b.code));let tv=0;
  S.nl.forEach(n=>{const a=KK.act[n.id];if(a!==undefined&&a!=='')tv+=(parseNum(a)-sys[n.id])*cu(n)});
  $('#kkT').innerHTML=`<table class="lines"><thead><tr><th>Mã</th><th>Nguyên liệu</th><th class="c">ĐVT</th><th class="n">Tồn sổ sách</th><th class="n" style="width:140px">Thực tế</th><th class="n">Chênh lệch</th><th class="n">Giá trị chênh lệch</th></tr></thead><tbody>${list.map(n=>{const a=KK.act[n.id],has=a!==undefined&&a!=='',df=has?parseNum(a)-sys[n.id]:0;
    return `<tr><td><b>${esc(n.code)}</b></td><td>${esc(n.name)}</td><td class="c">${esc(n.unit)}</td><td class="n">${fmtD(sys[n.id],1)}</td><td><input class="cin" type="number" step="any" value="${has?a:''}" placeholder="-" oninput="KK.act['${n.id}']=this.value;kkRow(this,'${n.id}')"></td><td class="n" data-df style="color:${df<0?'var(--danger)':df>0?'var(--in)':'inherit'}">${has?(df>0?'+':'')+fmtD(df,1):''}</td><td class="n" data-dv>${has?fmt(df*cu(n)):''}</td></tr>`}).join('')}</tbody>
    <tfoot><tr><td colspan="6">Tổng giá trị chênh lệch (âm là hao hụt)</td><td class="n" id="kkTv" style="color:${tv<0?'var(--danger)':'inherit'}">${fmt(tv)}</td></tr></tfoot></table>`}
function kkRow(inp,id){const sys=kkSys(),n=S.nl.find(x=>x.id===id),tr=inp.closest('tr'),a=KK.act[id],has=a!=='';const df=has?parseNum(a)-sys[id]:0;
  tr.querySelector('[data-df]').textContent=has?(df>0?'+':'')+fmtD(df,1):'';tr.querySelector('[data-df]').style.color=df<0?'var(--danger)':df>0?'var(--in)':'inherit';tr.querySelector('[data-dv]').textContent=has?fmt(df*cu(n)):'';
  let tv=0;S.nl.forEach(x=>{const v=KK.act[x.id];if(v!==undefined&&v!=='')tv+=(parseNum(v)-sys[x.id])*cu(x)});$('#kkTv').textContent=fmt(tv)}
function kkFill(){const sys=kkSys();S.nl.forEach(n=>{if(KK.act[n.id]===undefined||KK.act[n.id]==='')KK.act[n.id]=String(Math.round(sys[n.id]*10)/10)});kkTable();toast('Đã điền thực tế bằng sổ sách, chỉ cần sửa dòng có chênh lệch')}
function kkSave(){const sys=kkSys(),ls=S.nl.filter(n=>KK.act[n.id]!==undefined&&KK.act[n.id]!=='').map(n=>({nl:n.id,sys:Math.round(sys[n.id]*100)/100,act:parseNum(KK.act[n.id])}));
  if(!ls.length)return toast('Chưa ghi số thực tế nào','err');if(!KK.d)return toast('Chưa chọn ngày','err');
  const no=nextNo(S.counts,'KK',3);S.counts.push({id:'k'+uid(),no,d:KK.d,note:KK.note.trim(),lines:ls});save();toast(`Đã lưu ${no}: ${ls.length} nguyên liệu`);KK={d:TODAYS,note:'',act:{},q:''};renderCount()}
function kkHist(){const c=C(),list=S.counts.slice().sort((a,b)=>b.d.localeCompare(a.d));
  $('#kkH').innerHTML=list.length?`<div class="tbl-wrap"><table><thead><tr><th>Số phiếu</th><th>Ngày</th><th>Ghi chú</th><th class="n">Số NL kiểm</th><th>Chênh lệch lớn nhất</th><th class="n">Tổng giá trị chênh lệch</th><th></th></tr></thead><tbody>${list.map(k=>{const v=sum(k.lines,l=>(l.act-l.sys)*cu(c.nl[l.nl]));const big=k.lines.slice().sort((a,b)=>Math.abs((b.act-b.sys)*cu(c.nl[b.nl]))-Math.abs((a.act-a.sys)*cu(c.nl[a.nl])))[0];const bn=big&&c.nl[big.nl];
    return `<tr><td><b>${k.no}</b></td><td>${vnDate(k.d)}</td><td>${esc(k.note)}</td><td class="n">${k.lines.length}</td><td>${bn?esc(bn.name)+' <span class="muted">'+fmtD(big.act-big.sys,1)+' '+esc(bn.unit)+'</span>':''}</td><td class="n" style="color:${v<0?'var(--danger)':'inherit'}"><b>${fmt(v)}</b></td><td class="acts-c"><button class="btn sm ico danger" title="Xóa" onclick="kkDel('${k.id}')">${IC.trash}</button></td></tr>`}).join('')}</tbody></table></div>`:'<div class="empty">Chưa có phiếu kiểm kê</div>'}
async function kkDel(id){const k=S.counts.find(x=>x.id===id);if(!await ask(`Xóa phiếu kiểm kê <b>${esc(k.no)}</b>? Tồn kho sẽ quay về số sổ sách trước khi kiểm.`))return;S.counts=S.counts.filter(x=>x.id!==id);save();toast('Đã xóa phiếu '+k.no);rerender()}

/* =========================================================
   BÁO CÁO XUẤT NHẬP TỒN NGUYÊN LIỆU
   ========================================================= */
function xnt(f,t){const c=C(),R={};S.nl.forEach(n=>R[n.id]={n,open:+n.open||0,inQ:0,inV:0,use:0,adj:0});
  S.imports.forEach(p=>p.lines.forEach(l=>{const r=R[l.nl];if(!r)return;const q=(+l.q||0)*(+r.n.packSize||1);if(p.d<f)r.open+=q;else if(p.d<=t){r.inQ+=q;r.inV+=(+l.q||0)*(+l.p||0)}}));
  S.counts.forEach(k=>k.lines.forEach(l=>{const r=R[l.nl];if(!r)return;const q=(+l.act||0)-(+l.sys||0);if(k.d<f)r.open+=q;else if(k.d<=t)r.adj+=q}));
  S.orders.forEach(o=>{const pre=o.d<f;if(!pre&&o.d>t)return;o.lines.forEach(l=>useOf(c.mm[l.m],l.s,l.q,c.nl,(id,q)=>{if(pre)R[id].open-=q;else R[id].use+=q}))});
  return Object.values(R).map(r=>{r.close=r.open+r.inQ-r.use+r.adj;const u=cu(r.n);r.openV=r.open*u;r.useV=r.use*u;r.adjV=r.adj*u;r.closeV=Math.max(0,r.close)*u;return r})}
const XF={f:'',t:'',g:'',q:''};
function renderXnt(){const e=$('#page-xnt');
  if(!e.dataset.built){XF.f=rangeOf('month').from;XF.t=TODAYS;
    e.innerHTML=`<div class="toolbar"><div class="seg" id="xQ"><button data-v="today">Hôm nay</button><button data-v="7d">7 ngày</button><button data-v="month" class="on">Tháng này</button><button data-v="prev">Tháng trước</button><button data-v="quarter">Quý này</button></div>
      <input type="date" class="inp" id="xF" value="${XF.f}"><span class="muted">đến</span><input type="date" class="inp" id="xT" value="${XF.t}"><select class="inp" id="xG"></select>
      <div class="search grow" style="min-width:160px">${IC.search}<input class="inp" id="xS" placeholder="Tìm nguyên liệu..."></div>
      <button class="btn xl" onclick="exportXnt()">${IC.xl}Xuất Excel</button><button class="btn pri" onclick="window.print()">${IC.print}In báo cáo</button></div>
      <div class="print-h"><h2>BÁO CÁO XUẤT NHẬP TỒN NGUYÊN LIỆU</h2><div id="xPr"></div></div>
      <div class="hero x4" id="xHero"></div><div class="card"><div class="tbl-wrap" id="xTb"></div></div>`;
    segBind('#xQ',v=>{const r=rangeOf(v);XF.f=r.from;XF.t=r.to>TODAYS?TODAYS:r.to;$('#xF').value=XF.f;$('#xT').value=XF.t;renderXnt()});
    $('#xF').oninput=ev=>{XF.f=ev.target.value;$$('#xQ button').forEach(b=>b.classList.remove('on'));renderXnt()};$('#xT').oninput=ev=>{XF.t=ev.target.value;$$('#xQ button').forEach(b=>b.classList.remove('on'));renderXnt()};
    $('#xG').onchange=ev=>{XF.g=ev.target.value;renderXnt()};$('#xS').oninput=ev=>{XF.q=ev.target.value;renderXnt()};e.dataset.built=1}
  $('#xG').innerHTML='<option value="">Mọi nhóm</option>'+[...new Set(S.nl.map(n=>n.grp))].map(g=>`<option ${g===XF.g?'selected':''}>${esc(g)}</option>`).join('');
  const d=xntRows(),T=k=>sum(d,r=>r[k]);
  $('#xPr').textContent=`Từ ngày ${vnDate(XF.f)} đến ngày ${vnDate(XF.t)}${co().name?' · '+co().name:''}`;
  const fb=(lb,v,sub,ic)=>`<div><div class="h-k">${lb}</div><div class="h-v" style="font-size:26px">${short(v)} <small>₫</small></div><div class="h-sub">${sub}</div></div>`;
  $('#xHero').innerHTML=fb('TỒN ĐẦU KỲ',T('openV'),'Theo giá nhập hiện tại')+fb('NHẬP TRONG KỲ',T('inV'),`${S.imports.filter(p=>p.d>=XF.f&&p.d<=XF.t).length} phiếu nhập`)+fb('XUẤT BÁN THEO ĐỊNH LƯỢNG',T('useV'),`Hao hụt kiểm kê ${short(T('adjV'))} ₫`)+fb('TỒN CUỐI KỲ',T('closeV'),`${d.filter(r=>r.close<=r.n.min).length} nguyên liệu dưới mức tối thiểu`);
  $('#xTb').innerHTML=d.length?`<table><thead><tr><th class="c">STT</th><th>Nguyên liệu</th><th class="c">ĐVT</th><th class="n">Tồn đầu</th><th class="n">Nhập</th><th class="n">Xuất bán</th><th class="n">Kiểm kê +/-</th><th class="n">Tồn cuối</th><th class="n">Giá trị xuất</th><th class="n">Giá trị tồn cuối</th><th>Trạng thái</th></tr></thead><tbody>${pgSlice('xnt',d,50).map((r,i)=>{const k=r.close<=0?'zero':r.close<=r.n.min?'low':'ok';
    return `<tr><td class="c muted">${pgOff('xnt')+i+1}</td><td><div class="pcell"><b>${esc(r.n.name)}</b><small>${esc(r.n.code)} · ${esc(r.n.grp)}</small></div></td><td class="c">${esc(r.n.unit)}</td><td class="n">${fmtD(r.open,1)}</td><td class="n" style="color:var(--in)">${r.inQ?fmtD(r.inQ,1):'-'}</td><td class="n" style="color:var(--out)">${r.use?fmtD(r.use,1):'-'}</td><td class="n" style="color:${r.adj<0?'var(--danger)':'inherit'}">${r.adj?fmtD(r.adj,1):'-'}</td><td class="n"><b>${fmtD(r.close,1)}</b></td><td class="n">${fmt(r.useV)}</td><td class="n">${fmt(r.closeV)}</td><td><span class="tag ${STT[k][0]}">${STT[k][1]}</span></td></tr>`}).join('')}</tbody>
    <tfoot><tr><td></td><td colspan="2">TỔNG CỘNG ${d.length} nguyên liệu</td><td class="n">${fmt(T('openV'))} ₫</td><td class="n">${fmt(T('inV'))} ₫</td><td class="n">${fmt(T('useV'))} ₫</td><td class="n">${fmt(T('adjV'))} ₫</td><td></td><td class="n">${fmt(T('useV'))}</td><td class="n">${fmt(T('closeV'))}</td><td></td></tr></tfoot></table>${pgBar('xnt',d.length,renderXnt)}`:'<div class="empty">Không có nguyên liệu phù hợp</div>';
  countUp(e)}
function xntRows(){return xnt(XF.f,XF.t).filter(r=>(!XF.g||r.n.grp===XF.g)&&(!XF.q||matchQ(XF.q,r.n.code+' '+r.n.name))).sort((a,b)=>a.n.code.localeCompare(b.n.code))}
const xntCols=()=>[{label:'STT',type:'int',width:6},{label:'Mã NL',width:9},{label:'Nguyên liệu',width:28},{label:'Nhóm',width:13},{label:'ĐVT',width:7},{label:'Tồn đầu',type:'num',width:11},{label:'Nhập',type:'num',width:11},{label:'Xuất bán theo định lượng',type:'num',width:13},{label:'Kiểm kê +/-',type:'num',width:11},{label:'Tồn cuối',type:'num',width:11},{label:'Giá vốn / đv',type:'num',width:11},{label:'Giá trị nhập',type:'money',sum:true},{label:'Giá trị xuất',type:'money',sum:true},{label:'Giá trị tồn cuối',type:'money',sum:true}];
const xntRow=(r,i)=>[i+1,r.n.code,r.n.name,r.n.grp,r.n.unit,r.open,r.inQ,r.use,r.adj,r.close,cu(r.n),r.inV,r.useV,r.closeV];
function exportXnt(){XLSX.save(`Xuat nhap ton nguyen lieu ${XF.f} den ${XF.t}`,[{name:'Xuất nhập tồn NL',title:'BÁO CÁO XUẤT NHẬP TỒN NGUYÊN LIỆU',subtitles:[co().name||'Quán cà phê',`Từ ngày ${vnDate(XF.f)} đến ngày ${vnDate(XF.t)}`],totals:true,columns:xntCols(),rows:xntRows().map(xntRow)}])}

/* =========================================================
   BÁO CÁO BÁN HÀNG
   ========================================================= */
const SF={f:'',t:'',tab:'mon'};
function renderSales(){const e=$('#page-sales');
  if(!e.dataset.built){SF.f=rangeOf('month').from;SF.t=TODAYS;
    e.innerHTML=`<div class="toolbar"><div class="seg" id="sQ"><button data-v="today">Hôm nay</button><button data-v="7d">7 ngày</button><button data-v="month" class="on">Tháng này</button><button data-v="prev">Tháng trước</button><button data-v="quarter">Quý này</button><button data-v="year">Năm nay</button></div>
      <input type="date" class="inp" id="sF" value="${SF.f}"><span class="muted">đến</span><input type="date" class="inp" id="sT" value="${SF.t}">
      <button class="btn xl" onclick="exportSales()">${IC.xl}Xuất Excel</button><button class="btn pri" onclick="window.print()">${IC.print}In báo cáo</button></div>
      <div class="toolbar"><div class="seg" id="sTab"><button data-v="mon" class="on">Theo món</button><button data-v="ngay">Theo ngày</button><button data-v="gio">Theo giờ</button><button data-v="tt">Thanh toán & kênh bán</button></div></div>
      <div class="print-h"><h2>BÁO CÁO BÁN HÀNG</h2><div id="sPr"></div></div><div class="kc-grid" id="sK"></div><div id="sBody"></div>`;
    segBind('#sQ',v=>{const r=rangeOf(v);SF.f=r.from;SF.t=r.to>TODAYS?TODAYS:r.to;$('#sF').value=SF.f;$('#sT').value=SF.t;renderSales()});
    segBind('#sTab',v=>{SF.tab=v;renderSales()});
    $('#sF').oninput=ev=>{SF.f=ev.target.value;renderSales()};$('#sT').oninput=ev=>{SF.t=ev.target.value;renderSales()};e.dataset.built=1}
  const a=agg(SF.f,SF.t),c=C(),TAB={mon:'theo món',ngay:'theo ngày',gio:'theo giờ',tt:'theo thanh toán và kênh bán'};
  $('#sPr').textContent=`Từ ngày ${vnDate(SF.f)} đến ngày ${vnDate(SF.t)} · ${TAB[SF.tab]}${co().name?' · '+co().name:''}`;
  $('#sK').innerHTML=kc({c:CSSV('--chu-dao'),cb:'var(--cd-nhat)',icon:IC.money,label:'Doanh thu',value:a.rev,unit:'₫',sub:`${fmt(a.n)} order · ${fmt(a.items)} ly`})+kc({c:'#f0663a',cb:'var(--outbg)',icon:IC.box,label:'Giá vốn theo định lượng',value:a.cogs,unit:'₫',sub:`Bằng ${pct(a.rev?a.cogs/a.rev*100:0)} doanh thu`})+kc({c:'#16a36a',cb:'var(--inbg)',icon:IC.trend,label:'Lãi gộp',value:a.gp,unit:'₫',sub:`Biên lãi ${pct(a.rev?a.gp/a.rev*100:0)}`})+kc({c:'#8b5cf6',cb:'#f1ebff',icon:IC.cal,label:'Bình quân / ngày',value:a.nd?a.rev/a.nd:0,unit:'₫',sub:`${a.nd} ngày có bán · giảm giá ${short(a.disc)} ₫`});
  const rows=salesRows(a,c),b=$('#sBody');
  if(SF.tab==='mon'){const top=rows.slice(0,10);
    b.innerHTML=`<div class="grid-c"><div class="card"><div class="card-h"><h3>Top 10 món theo doanh thu</h3></div><div class="card-b">${hbars(top.map(r=>({label:r[1],value:r[5],sub:fmt(r[3])+' ly',color:gcol(r[2])})),short)}</div></div><div class="card"><div class="card-h"><h3>Doanh thu theo nhóm món</h3></div><div class="card-b">${donut(Object.entries(groupBy(rows,r=>r[2])).map(([g,rs])=>({label:g,value:sum(rs,r=>r[5]),color:gcol(g)})).sort((x,y)=>y.value-x.value),'Doanh thu',short)}</div></div></div>
    <div class="card"><div class="tbl-wrap"><table><thead><tr><th class="c">#</th><th>Món</th><th>Nhóm</th><th class="n">Số ly</th><th>Theo size</th><th class="n">Doanh thu</th><th class="n">Giá vốn</th><th class="n">Lãi gộp</th><th class="n">% giá vốn</th><th class="n">Tỷ trọng DT</th></tr></thead><tbody>${rows.map((r,i)=>`<tr><td class="c muted">${i+1}</td><td><b>${esc(r[1])}</b></td><td><span class="tag cat">${esc(r[2])}</span></td><td class="n">${fmt(r[3])}</td><td class="muted">${esc(r[4])}</td><td class="n"><b>${fmt(r[5])}</b></td><td class="n">${fmt(r[6])}</td><td class="n" style="color:var(--in)">${fmt(r[7])}</td><td class="n">${pct(r[8])}</td><td class="n">${pct(r[9])}</td></tr>`).join('')}</tbody><tfoot><tr><td></td><td colspan="2">TỔNG CỘNG</td><td class="n">${fmt(sum(rows,r=>r[3]))}</td><td></td><td class="n">${fmt(a.rev)}</td><td class="n">${fmt(a.cogs)}</td><td class="n">${fmt(a.gp)}</td><td class="n">${pct(a.rev?a.cogs/a.rev*100:0)}</td><td class="n">100%</td></tr></tfoot></table></div></div>`}
  else if(SF.tab==='ngay'){b.innerHTML=`<div class="card" style="margin-bottom:18px"><div class="card-h"><h3>Doanh thu và lãi gộp theo ngày</h3></div><div class="card-b">${combo({labels:rows.map(r=>r[0].slice(8)+'/'+r[0].slice(5,7)),bars:[{name:'Doanh thu',data:rows.map(r=>r[5]),color:CSSV('--chu-dao')}],lines:[{name:'Lãi gộp',data:rows.map(r=>r[7]),color:'#16a36a'}],H:280})}</div></div>
    <div class="card"><div class="tbl-wrap"><table><thead><tr><th>Ngày</th><th>Thứ</th><th class="n">Số order</th><th class="n">Số ly</th><th class="n">Giảm giá</th><th class="n">Doanh thu</th><th class="n">Giá vốn</th><th class="n">Lãi gộp</th><th class="n">TB / order</th></tr></thead><tbody>${rows.slice().reverse().map(r=>`<tr><td><b>${vnDate(r[0])}</b></td><td>${r[1]}</td><td class="n">${fmt(r[2])}</td><td class="n">${fmt(r[3])}</td><td class="n">${fmt(r[4])}</td><td class="n"><b>${fmt(r[5])}</b></td><td class="n">${fmt(r[6])}</td><td class="n" style="color:var(--in)">${fmt(r[7])}</td><td class="n">${fmt(r[8])}</td></tr>`).join('')}</tbody><tfoot><tr><td colspan="2">TỔNG ${rows.length} ngày</td><td class="n">${fmt(a.n)}</td><td class="n">${fmt(a.items)}</td><td class="n">${fmt(a.disc)}</td><td class="n">${fmt(a.rev)}</td><td class="n">${fmt(a.cogs)}</td><td class="n">${fmt(a.gp)}</td><td class="n">${fmt(a.n?a.rev/a.n:0)}</td></tr></tfoot></table></div></div>`}
  else if(SF.tab==='gio'){b.innerHTML=`<div class="card" style="margin-bottom:18px"><div class="card-h"><h3>Doanh thu và số order theo khung giờ</h3><span class="hint">Biết giờ đông khách để xếp ca nhân viên</span></div><div class="card-b">${combo({labels:rows.map(r=>r[0].split('-')[0]),tipL:rows.map(r=>r[0]),bars:[{name:'Doanh thu',data:rows.map(r=>r[2]),color:CSSV('--cd-sang')}],H:280,bw:24})}</div></div>
    <div class="card"><div class="tbl-wrap"><table><thead><tr><th>Khung giờ</th><th class="n">Số order</th><th class="n">Doanh thu</th><th class="n">TB order / ngày</th><th class="n">TB doanh thu / ngày</th><th class="n">Tỷ trọng</th></tr></thead><tbody>${rows.map(r=>`<tr><td><b>${r[0]}</b></td><td class="n">${fmt(r[1])}</td><td class="n"><b>${fmt(r[2])}</b></td><td class="n">${fmtD(r[3],1)}</td><td class="n">${fmt(r[4])}</td><td class="n">${pct(r[5])}</td></tr>`).join('')}</tbody><tfoot><tr><td>TỔNG</td><td class="n">${fmt(a.n)}</td><td class="n">${fmt(a.rev)}</td><td></td><td></td><td class="n">100%</td></tr></tfoot></table></div></div>`}
  else{const tb=(t,obj)=>{const e=Object.entries(obj).sort((x,y)=>y[1]-x[1]);return `<div class="card"><div class="card-h"><h3>${t}</h3></div><div class="card-b">${donut(e.map(([k,v],i)=>({label:k,value:v,color:[CSSV('--chu-dao'),'#16a36a','#8b5cf6','#e6a100','#64748b'][i%5]})),'Doanh thu',short)}</div></div>`};
    b.innerHTML=`<div class="grid-c">${tb('Theo hình thức thanh toán',a.pay)}${tb('Theo kênh bán',a.ch)}</div><div class="card"><div class="tbl-wrap"><table><thead><tr><th>Nhóm</th><th>Tên</th><th class="n">Doanh thu</th><th class="n">Tỷ trọng</th></tr></thead><tbody>${rows.map(r=>`<tr><td class="muted">${r[0]}</td><td><b>${esc(r[1])}</b></td><td class="n">${fmt(r[2])}</td><td class="n">${pct(r[3])}</td></tr>`).join('')}</tbody></table></div></div>`}
  countUp($('#sK'))}
function salesRows(a,c){a=a||agg(SF.f,SF.t);c=c||C();
  if(SF.tab==='mon')return Object.entries(a.byM).map(([id,o])=>{const m=c.mm[id]||{name:'(đã xóa)',grp:'Khác',code:''};return [m.code,m.name,m.grp,o.q,Object.entries(o.sz).map(([s,q])=>s+': '+q).join(', '),o.rev,o.cogs,o.rev-o.cogs,o.rev?o.cogs/o.rev*100:0,a.rev?o.rev/a.rev*100:0]}).sort((x,y)=>y[5]-x[5]);
  if(SF.tab==='ngay')return Object.keys(a.day).sort().map(d=>{const x=a.day[d];return [d,WD[pd(d).getDay()],x.n,x.items,x.disc,x.rev,x.cogs,x.rev-x.cogs,x.n?x.rev/x.n:0]});
  if(SF.tab==='gio'){const o=[];for(let h=0;h<24;h++)if(a.hourN[h])o.push([h+'h-'+(h+1)+'h',a.hourN[h],a.hour[h],a.nd?a.hourN[h]/a.nd:0,a.nd?a.hour[h]/a.nd:0,a.rev?a.hour[h]/a.rev*100:0]);return o}
  return [...Object.entries(a.pay).sort((x,y)=>y[1]-x[1]).map(([k,v])=>['Thanh toán',k,v,a.rev?v/a.rev*100:0]),...Object.entries(a.ch).sort((x,y)=>y[1]-x[1]).map(([k,v])=>['Kênh bán',k,v,a.rev?v/a.rev*100:0])]}
function exportSales(){const rows=salesRows(),T={mon:'Theo món',ngay:'Theo ngày',gio:'Theo giờ',tt:'Thanh toán và kênh'};
  const cols={mon:[{label:'Mã món',width:9},{label:'Món',width:26},{label:'Nhóm',width:12},{label:'Số ly',type:'int',sum:true},{label:'Theo size',width:18},{label:'Doanh thu',type:'money',sum:true},{label:'Giá vốn',type:'money',sum:true},{label:'Lãi gộp',type:'money',sum:true},{label:'% giá vốn',type:'pct'},{label:'Tỷ trọng DT',type:'pct'}],
    ngay:[{label:'Ngày',type:'date'},{label:'Thứ',width:10},{label:'Số order',type:'int',sum:true},{label:'Số ly',type:'int',sum:true},{label:'Giảm giá',type:'money',sum:true},{label:'Doanh thu',type:'money',sum:true},{label:'Giá vốn',type:'money',sum:true},{label:'Lãi gộp',type:'money',sum:true},{label:'TB / order',type:'money'}],
    gio:[{label:'Khung giờ',width:12},{label:'Số order',type:'int',sum:true},{label:'Doanh thu',type:'money',sum:true},{label:'TB order / ngày',type:'num'},{label:'TB doanh thu / ngày',type:'money'},{label:'Tỷ trọng',type:'pct'}],
    tt:[{label:'Nhóm',width:12},{label:'Tên',width:18},{label:'Doanh thu',type:'money'},{label:'Tỷ trọng',type:'pct'}]}[SF.tab];
  const R=rows;
  XLSX.save(`Bao cao ban hang ${T[SF.tab]} ${SF.f} den ${SF.t}`,[{name:T[SF.tab],title:'BÁO CÁO BÁN HÀNG '+T[SF.tab].toUpperCase(),subtitles:[co().name||'Quán cà phê',`Từ ngày ${vnDate(SF.f)} đến ngày ${vnDate(SF.t)}`],totals:SF.tab!=='tt',columns:cols,rows:R}])}

