function sheetsAll(){const c=C(),orders=S.orders.slice().sort((a,b)=>(a.d+a.t).localeCompare(b.d+b.t));
  const det=[];orders.forEach(o=>o.lines.forEach(l=>{const m=c.mm[l.m];det.push([o.no,o.d,o.t,o.ch,m?m.code:'',m?m.name:'(đã xóa)',l.s,l.q,l.p,l.q*l.p,l.q*mCost(m,l.s,c),o.pay])}));
  const mn=[],dl=[];S.menu.forEach(m=>m.sizes.forEach((s,i)=>{const cg=mCost(m,s.n,c);mn.push([m.code,m.name,m.grp,s.n,s.p,cg,s.p-cg,s.p?cg/s.p*100:0,m.on===false?'Ngừng bán':'Đang bán']);m.rec.forEach(r=>{const n=c.nl[r.nl];if(n&&r.q[i])dl.push([m.code,m.name,s.n,n.code,n.name,r.q[i],n.unit,cu(n),r.q[i]*cu(n)])})}));
  const imp=[];S.imports.slice().sort((a,b)=>a.d.localeCompare(b.d)).forEach(p=>p.lines.forEach(l=>{const n=c.nl[l.nl]||{};imp.push([p.no,p.d,p.sup,n.code,n.name,n.pack,l.q,l.q*(n.packSize||1),n.unit,l.p,l.q*l.p])}));
  const kk=[];S.counts.forEach(k=>k.lines.forEach(l=>{const n=c.nl[l.nl]||{};kk.push([k.no,k.d,n.code,n.name,n.unit,l.sys,l.act,l.act-l.sys,(l.act-l.sys)*cu(n)])}));
  const mf=rangeOf('month').from;
  return [{name:'Order',title:'DANH SÁCH ORDER',columns:ordCols(),rows:orders.map(o=>ordRow(o,c)),totals:true},
    {name:'Chi tiết order',title:'CHI TIẾT MÓN THEO ORDER',columns:[{label:'Số HD',width:10},{label:'Ngày',type:'date'},{label:'Giờ',width:7},{label:'Kênh',width:11},{label:'Mã món',width:9},{label:'Món',width:24},{label:'Size',width:7},{label:'SL',type:'int',sum:true},{label:'Đơn giá',type:'money'},{label:'Thành tiền',type:'money',sum:true},{label:'Giá vốn',type:'money',sum:true},{label:'Thanh toán',width:13}],rows:det,totals:true},
    {name:'Menu & giá vốn',title:'MENU, GIÁ BÁN VÀ GIÁ VỐN THEO ĐỊNH LƯỢNG',columns:[{label:'Mã món',width:9},{label:'Món',width:24},{label:'Nhóm',width:12},{label:'Size',width:7},{label:'Giá bán',type:'money'},{label:'Giá vốn',type:'money'},{label:'Lãi gộp',type:'money'},{label:'% giá vốn',type:'pct'},{label:'Trạng thái',width:11}],rows:mn},
    {name:'Định lượng',title:'ĐỊNH LƯỢNG NGUYÊN LIỆU CHO 1 LY',columns:[{label:'Mã món',width:9},{label:'Món',width:24},{label:'Size',width:7},{label:'Mã NL',width:9},{label:'Nguyên liệu',width:26},{label:'Định lượng',type:'num'},{label:'ĐVT',width:7},{label:'Giá vốn / đv',type:'num'},{label:'Thành tiền',type:'num'}],rows:dl},
    {name:'Nguyên liệu',title:'DANH MỤC NGUYÊN LIỆU VÀ TỒN KHO',columns:[{label:'Mã NL',width:9},{label:'Nguyên liệu',width:26},{label:'Nhóm',width:12},{label:'ĐVT',width:7},{label:'Quy cách nhập',width:14},{label:'Quy đổi',type:'num'},{label:'Giá nhập / quy cách',type:'money'},{label:'Giá vốn / đv',type:'num'},{label:'Tồn đầu',type:'num'},{label:'Tồn hiện tại',type:'num'},{label:'Tồn tối thiểu',type:'num'},{label:'Giá trị tồn',type:'money',sum:true},{label:'Trạng thái',width:10}],rows:S.nl.map(n=>{const s=c.st[n.id]||0;return [n.code,n.name,n.grp,n.unit,n.pack,n.packSize,n.packPrice,cu(n),n.open,s,n.min,Math.max(0,s)*cu(n),STT[nlSt(n,c)][1]]}),totals:true},
    {name:'Phiếu nhập NL',title:'PHIẾU NHẬP NGUYÊN LIỆU',columns:[{label:'Số phiếu',width:9},{label:'Ngày',type:'date'},{label:'Nhà cung cấp',width:26},{label:'Mã NL',width:9},{label:'Nguyên liệu',width:26},{label:'Quy cách',width:13},{label:'SL nhập',type:'num'},{label:'Quy đổi',type:'num'},{label:'ĐVT',width:7},{label:'Đơn giá',type:'money'},{label:'Thành tiền',type:'money',sum:true}],rows:imp,totals:true},
    {name:'Kiểm kê',title:'KIỂM KÊ KHO NGUYÊN LIỆU',columns:[{label:'Số phiếu',width:9},{label:'Ngày',type:'date'},{label:'Mã NL',width:9},{label:'Nguyên liệu',width:26},{label:'ĐVT',width:7},{label:'Tồn sổ sách',type:'num'},{label:'Thực tế',type:'num'},{label:'Chênh lệch',type:'num'},{label:'Giá trị chênh lệch',type:'money',sum:true}],rows:kk,totals:true},
    {name:'XNT tháng này',title:'XUẤT NHẬP TỒN NGUYÊN LIỆU THÁNG '+(TODAY.getMonth()+1)+'/'+TODAY.getFullYear(),columns:xntCols(),rows:xnt(mf,TODAYS).sort((a,b)=>a.n.code.localeCompare(b.n.code)).map(xntRow),totals:true}]}

boot();

/* Standalone Blade theme selector: separate from business JSON */
(function(){
 const KEY='coffee_shop_sales_theme_v1';
 const themes={ruby:'#C62828',ocean:'#087E9B',emerald:'#16835D',indigo:'#4F46E5'};
 function apply(k){if(!themes[k])k='ruby';document.documentElement.dataset.coffeeTheme=k;document.documentElement.style.setProperty('--coffee-accent',themes[k]);document.querySelectorAll('[data-coffee-theme]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.coffeeTheme===k)));}
 function render(){const host=document.getElementById('coffee-theme-settings');if(!host)return;host.innerHTML='<strong>Màu giao diện</strong><div class="coffee-theme-options">'+Object.entries(themes).map(([k,c])=>'<button type="button" data-coffee-theme="'+k+'" style="--swatch:'+c+'" aria-pressed="false">'+k+'</button>').join('')+'</div>';host.addEventListener('click',e=>{const b=e.target.closest('[data-coffee-theme]');if(!b)return;try{localStorage.setItem(KEY,b.dataset.coffeeTheme)}catch(_){}apply(b.dataset.coffeeTheme)});apply(read());}
 function read(){try{return localStorage.getItem(KEY)||'ruby'}catch(_){return 'ruby'}}
 if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',render);else render();apply(read());
})();
